import json
from itertools import permutations

def compute_itinerary():
    # Input variables
    total_days = 10
    durations = {
        "Krakow": 2,
        "Dubrovnik": 7,
        "Frankfurt": 3,
    }
    cities = list(durations.keys())
    wedding_city = "Krakow"
    wedding_start_day = 9
    wedding_end_day = 10  # inclusive

    # Direct flights (bidirectional)
    direct_flights = {
        ("Frankfurt", "Krakow"), ("Krakow", "Frankfurt"),
        ("Dubrovnik", "Frankfurt"), ("Frankfurt", "Dubrovnik")
    }

    def connected(a, b):
        return (a, b) in direct_flights

    # Generate valid sequences (paths) over the 3 cities using only direct flights
    valid_orders = []
    for order in permutations(cities, 3):
        if all(connected(order[i], order[i+1]) for i in range(2)):
            valid_orders.append(order)

    # Try to construct an itinerary for each valid order that fits durations and wedding constraints
    best_itinerary = None
    for order in valid_orders:
        # Number of transitions is len(order) - 1; each transition day is counted in both adjacent cities
        transitions = len(order) - 1
        required_total = sum(durations.values()) - transitions
        if required_total != total_days:
            continue

        # Build consecutive blocks with overlapping boundary days as travel days
        blocks = []
        start_day = 1
        end_day = None
        for i, city in enumerate(order):
            dur = durations[city]
            if i == 0:
                # First city runs from start_day to start_day + dur - 1
                end_day = start_day + dur - 1
            else:
                # Next city starts on previous end_day (travel day counts for both)
                start_day = end_day
                end_day = start_day + dur - 1
            blocks.append((city, start_day, end_day))

        # Ensure we exactly fill total_days
        if end_day != total_days:
            continue

        # Check wedding constraint: be in wedding_city for both wedding days (inclusive range)
        wedding_ok = False
        for city, s, e in blocks:
            if city == wedding_city and (s <= wedding_start_day <= e) and (s <= wedding_end_day <= e):
                wedding_ok = True
                break
        if not wedding_ok:
            continue

        # If multiple itineraries were possible, one could apply tie-breaking here; take the first feasible
        best_itinerary = blocks
        break

    # Prepare output
    if best_itinerary is None:
        result = {"itinerary": []}
    else:
        itinerary = []
        for city, s, e in best_itinerary:
            itinerary.append({
                "day_range": f"Day {s}-{e}",
                "place": city
            })
        result = {"itinerary": itinerary}

    print(json.dumps(result, ensure_ascii=False))

if __name__ == "__main__":
    compute_itinerary()
